let runtime

/**
 * Active sessions, mapped by multiplayer session ids (activeSessionId)
 */
const sessions = new Map()

/**
 * Active connections, mapping comms session to multiplayer session (activeSessionId)
 */
const connections = new Map()

/**
 * Map of activeSessionId to publicSessionId
 * activeSessionId: generated by the client and not shared to other multiplayer clients
 * publicSessionId: generated by the server provided to the client on connect/reconnect.
 *                  Any other multiplayer clients will use this to identify this session.
 */
const publicSessions = new Map()

function getSessionsList() {
    return Array.from(sessions.values()).filter(session => session.active)
}

module.exports = {
    init: function(_runtime) {
        runtime = _runtime
        runtime.events.on('comms:connection-removed', (opts) => {
            const existingSessionId = connections.get(opts.session)
            if (existingSessionId) {
                const publicSessionId = publicSessions.get(existingSessionId)
                connections.delete(opts.session)
                const session = sessions.get(existingSessionId)
                if (session) {
                    session.active = false
                    session.idleTimeout = setTimeout(() => {
                        sessions.delete(existingSessionId)
                        publicSessions.delete(existingSessionId)
                    }, 30000)
                    runtime.events.emit('comms', {
                        topic: "multiplayer/connection-removed",
                        data: { session: publicSessionId }
                    })
                }
            }
        })
        runtime.events.on('comms:message:multiplayer/connect', (opts) => {
            runtime.log.debug('multiplayer connect', opts.data.session, opts.user ? opts.user.username : 'anonymous')
            let session
            if (!sessions.has(opts.data.session)) {
                // Brand new session

                // Check the session identifier is valid - if not, ignore the session request
                if (!opts.data.session || !/^[a-zA-Z0-9]+$/.test(opts.data.session)) {
                    runtime.log.debug(`multiplayer invalid session:${opts.data.session}`)
                    return
                }
                let user = opts.user
                if (!user || user.anonymous) {
                    user = user || { anonymous: true }
                    user.username = `Anon ${Math.floor(Math.random()*100)}`
                }
                // Generate public session id
                const publicSessionId = 'PUB' + runtime.util.generateId() + 'PUB'
                session = {
                    session: publicSessionId,
                    user,
                    active: true
                }
                sessions.set(opts.data.session, session)
                publicSessions.set(opts.data.session, publicSessionId)
                connections.set(opts.session, opts.data.session)
                runtime.log.debug(`multiplayer new session:${opts.data.session} public:${publicSessionId} user:${user.username}`)
            } else {
                // Reconnected connection - keep existing state
                connections.set(opts.session, opts.data.session)
                // const existingConnection  = connections.get(opts.data.session)
                session = sessions.get(opts.data.session)
                session.active = true
                runtime.log.debug(`multiplayer reconnected session:${opts.data.session} public:${publicSessions.get(opts.data.session)} user:${session.user.username}`)
                clearTimeout(session.idleTimeout)
            }
            // Tell existing sessions about the new connection
            runtime.events.emit('comms', {
                topic: "multiplayer/connection-added",
                excludeSession: opts.session,
                data: session
            })

            // Send init info to new connection
            const initPacket = {
                topic: "multiplayer/init",
                data: { session: session.session, sessions: getSessionsList() },
                session: opts.session
            }
            // console.log('<<', initPacket)
            runtime.events.emit('comms', initPacket)
        })
        runtime.events.on('comms:message:multiplayer/disconnect', (opts) => {
            const existingSessionId = connections.get(opts.session)
            connections.delete(opts.session)
            sessions.delete(existingSessionId)
            const publicSessionId = publicSessions.get(existingSessionId)
            publicSessions.delete(existingSessionId)
            runtime.log.debug('multiplayer disconnect', existingSessionId, publicSessionId)
            runtime.events.emit('comms', {
                topic: "multiplayer/connection-removed",
                data: { session: publicSessionId, disconnected: true }
            })
        })
        runtime.events.on('comms:message:multiplayer/location', (opts) => {
            // console.log('>>>', opts.user, opts.data)

            const sessionId = connections.get(opts.session)
            const session = sessions.get(sessionId)
            const publicSessionId = publicSessions.get(sessionId)

            if (session) {
                // Validate payload contents
                // workspace: id of the flow tab they are on
                if (opts.data.workspace && !/^[a-zA-Z0-9.]+$/.test(opts.data.workspace)) {
                    return
                }
                // node: id of the node they are on
                if (opts.data.node && !/^[a-zA-Z0-9.]+$/.test(opts.data.node)) {
                    return
                }
                // x/y coordinates of the cursor position
                if (opts.data.cursor && (isNaN(opts.data.cursor.x) || isNaN(opts.data.cursor.y))) {
                    return
                }
                if (opts.user) {
                    if (session.user.anonymous !== opts.user.anonymous) {
                        session.user = opts.user
                        runtime.events.emit('comms', {
                            topic: 'multiplayer/connection-added',
                            excludeSession: opts.session,
                            data: session
                        })
                    }
                }

                session.location = opts.data

                const payload = {
                    session: publicSessionId,
                    workspace: opts.data.workspace,
                    node: opts.data.node,
                    cursor: opts.data.cursor
                }
                runtime.events.emit('comms', {
                    topic: 'multiplayer/location',
                    data: payload,
                    excludeSession: opts.session
                })
            }
        })
    }
}